// Builds js/fhir/ecr137-fhir-bundle.js: the compiled conversion stylesheet (SEF) plus every XML
// document the stylesheet reads through document()/doc(), keyed by repository-relative path.
// Loading these as a script lets index.html run the conversion when opened straight from disk.
// Usage (repo root): npx xslt3 -xsl:js/fhir/ecr137-cda2fhir.xslt -export:build/ecr137-cda2fhir.sef.json -nogo -relocate:on
//                    node tools/fhir/build-browser-bundle.mjs
import fs from 'fs'; import path from 'path';
const root = process.cwd();
const sef = fs.readFileSync(path.join(root, 'build/ecr137-cda2fhir.sef.json'), 'utf8');
const docs = {};
const add = rel => { docs[rel] = fs.readFileSync(path.join(root, rel), 'utf8'); };
const vendorDir = 'vendor/ecr-transforms/transforms';
for (const f of fs.readdirSync(path.join(root, vendorDir))) if (f.endsWith('.xml')) add(`${vendorDir}/${f}`);
// A relocated SEF resolves every module against one base URI: the upstream transform folder.
// The wrapper's display table is therefore registered beside it.
const base = `${vendorDir}/cda2fhir-r4/ecr137-cda2fhir.xslt`;
// cda2fhir-Narrative.xslt reads its own inline table (document('')), which resolves to that same base.
docs[base] = fs.readFileSync(path.join(root, `${vendorDir}/cda2fhir-r4/cda2fhir-Narrative.xslt`), 'utf8');
docs[`${vendorDir}/cda2fhir-r4/display-table.xml`] = fs.readFileSync(path.join(root, 'js/fhir/display-table.xml'), 'utf8');
const out = `/* GENERATED by tools/fhir/build-browser-bundle.mjs. Do not edit. */\n` +
  `window.ECR137_FHIR_BUNDLE = { stylesheet: '${base}', sef: ${sef}, docs: ${JSON.stringify(docs)} };\n`;
fs.writeFileSync(path.join(root, 'js/fhir/ecr137-fhir-bundle.js'), out);
console.log('js/fhir/ecr137-fhir-bundle.js', (out.length / 1048576).toFixed(1), 'MB,', Object.keys(docs).length, 'documents');
